package server

import (
	"context"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"os"
	"sync"
	"time"

	"github.com/google/uuid"
	"github.com/labstack/echo/v5"
	"github.com/labstack/echo/v5/middleware"
	"github.com/pkg/errors"

	"github.com/usememos/memos/internal/profile"
	storepb "github.com/usememos/memos/proto/gen/store"
	apiv1 "github.com/usememos/memos/server/router/api/v1"
	"github.com/usememos/memos/server/router/fileserver"
	"github.com/usememos/memos/server/router/frontend"
	"github.com/usememos/memos/server/router/mcp"
	"github.com/usememos/memos/server/router/rss"
	"github.com/usememos/memos/server/runner/s3presign"
	"github.com/usememos/memos/store"
)

const shutdownTimeout = 10 * time.Second

type Server struct {
	Secret  string
	Profile *profile.Profile
	Store   *store.Store

	echoServer *echo.Echo
	httpServer *http.Server
	sseHub     *apiv1.SSEHub

	backgroundRunnerCancels []context.CancelFunc
	backgroundRunnerWG      sync.WaitGroup
}

func NewServer(ctx context.Context, profile *profile.Profile, store *store.Store) (*Server, error) {
	s := &Server{
		Store:   store,
		Profile: profile,
	}

	echoServer := echo.New()
	echoServer.Use(middleware.Recover())
	echoServer.Use(newCORSMiddleware(profile))
	s.echoServer = echoServer

	instanceBasicSetting, err := s.getOrUpsertInstanceBasicSetting(ctx)
	if err != nil {
		return nil, errors.Wrap(err, "failed to get instance basic setting")
	}

	secret := "usememos"
	if !profile.Demo {
		secret = instanceBasicSetting.SecretKey
	}
	s.Secret = secret

	// Register healthz endpoint.
	echoServer.GET("/healthz", func(c *echo.Context) error {
		return c.String(http.StatusOK, "Service ready.")
	})

	// Serve frontend static files.
	frontend.NewFrontendService(profile, store).Serve(ctx, echoServer)

	rootGroup := echoServer.Group("")

	apiV1Service := apiv1.NewAPIV1Service(s.Secret, profile, store)
	s.sseHub = apiV1Service.SSEHub

	// Register HTTP file server routes BEFORE gRPC-Gateway to ensure proper range request handling for Safari.
	// This uses native HTTP serving (http.ServeContent) instead of gRPC for video/audio files.
	fileServerService := fileserver.NewFileServerService(s.Profile, s.Store, s.Secret)
	fileServerService.RegisterRoutes(echoServer)

	// Create and register RSS routes (needs markdown service from apiV1Service).
	rss.NewRSSService(s.Profile, s.Store, apiV1Service.MarkdownService).RegisterRoutes(rootGroup)

	// Register gRPC gateway as api v1 (includes SSE endpoint on CORS-enabled group).
	if err := apiV1Service.RegisterGateway(ctx, echoServer); err != nil {
		return nil, errors.Wrap(err, "failed to register gRPC gateway")
	}

	mcpService, err := mcp.NewMCPService(profile, echoServer)
	if err != nil {
		return nil, errors.Wrap(err, "failed to create MCP service")
	}
	mcpService.RegisterRoutes(echoServer)

	return s, nil
}

func (s *Server) Start(ctx context.Context) error {
	var address, network string
	if len(s.Profile.UNIXSock) == 0 {
		address = fmt.Sprintf("%s:%d", s.Profile.Addr, s.Profile.Port)
		network = "tcp"
	} else {
		address = s.Profile.UNIXSock
		network = "unix"
	}
	listener, err := net.Listen(network, address)
	if err != nil {
		return errors.Wrap(err, "failed to listen")
	}

	if network == "unix" {
		if err := os.Chmod(address, 0660); err != nil {
			_ = listener.Close()
			return errors.Wrap(err, "failed to chmod socket")
		}
	}

	// Start Echo server directly (no cmux needed - all traffic is HTTP).
	s.httpServer = &http.Server{Handler: s.echoServer}
	go func() {
		if err := s.httpServer.Serve(listener); err != nil && err != http.ErrServerClosed {
			slog.Error("failed to start echo server", "error", err)
		}
	}()
	s.startBackgroundRunners(ctx)

	return nil
}

func (s *Server) Shutdown(ctx context.Context) {
	ctx, cancel := context.WithTimeout(ctx, shutdownTimeout)
	defer cancel()

	slog.Info("server shutting down")

	s.stopBackgroundRunners()
	s.closeLongLivedConnections()
	s.shutdownHTTPServer(ctx)
	s.waitBackgroundRunners(ctx)

	// Close database connection.
	if err := s.Store.Close(); err != nil {
		slog.Error("failed to close database", slog.String("error", err.Error()))
	}

	slog.Info("memos stopped properly")
}

func (s *Server) startBackgroundRunners(ctx context.Context) {
	// Create a separate context for each background runner
	// This allows us to control cancellation for each runner independently
	s3Context, s3Cancel := context.WithCancel(ctx)

	// Store the cancel function so we can properly shut down runners
	s.backgroundRunnerCancels = append(s.backgroundRunnerCancels, s3Cancel)

	// Create and start S3 presign runner
	s3presignRunner := s3presign.NewRunner(s.Store)
	s3presignRunner.RunOnce(ctx)

	// Start continuous S3 presign runner
	s.backgroundRunnerWG.Add(1)
	go func() {
		defer s.backgroundRunnerWG.Done()
		s3presignRunner.Run(s3Context)
		slog.Info("s3presign runner stopped")
	}()

	slog.Info("background runners started")
}

func (s *Server) stopBackgroundRunners() {
	for _, cancelFunc := range s.backgroundRunnerCancels {
		if cancelFunc != nil {
			cancelFunc()
		}
	}
}

func (s *Server) waitBackgroundRunners(ctx context.Context) {
	done := make(chan struct{})
	go func() {
		s.backgroundRunnerWG.Wait()
		close(done)
	}()

	select {
	case <-done:
	case <-ctx.Done():
		select {
		case <-done:
			return
		default:
		}
		slog.Error("failed to stop background runners", slog.String("error", ctx.Err().Error()))
	}
}

func (s *Server) closeLongLivedConnections() {
	// Long-lived SSE requests do not finish on their own during http.Server.Shutdown.
	if s.sseHub != nil {
		s.sseHub.Close()
	}
}

func (s *Server) shutdownHTTPServer(ctx context.Context) {
	if s.httpServer == nil {
		return
	}
	if err := s.httpServer.Shutdown(ctx); err != nil {
		slog.Error("failed to shutdown server", slog.String("error", err.Error()))
		if closeErr := s.httpServer.Close(); closeErr != nil && closeErr != http.ErrServerClosed {
			slog.Error("failed to close server", slog.String("error", closeErr.Error()))
		}
	}
}

func (s *Server) getOrUpsertInstanceBasicSetting(ctx context.Context) (*storepb.InstanceBasicSetting, error) {
	instanceBasicSetting, err := s.Store.GetInstanceBasicSetting(ctx)
	if err != nil {
		return nil, errors.Wrap(err, "failed to get instance basic setting")
	}
	modified := false
	if instanceBasicSetting.SecretKey == "" {
		instanceBasicSetting.SecretKey = uuid.NewString()
		modified = true
	}
	if modified {
		instanceSetting, err := s.Store.UpsertInstanceSetting(ctx, &storepb.InstanceSetting{
			Key:   storepb.InstanceSettingKey_BASIC,
			Value: &storepb.InstanceSetting_BasicSetting{BasicSetting: instanceBasicSetting},
		})
		if err != nil {
			return nil, errors.Wrap(err, "failed to upsert instance setting")
		}
		instanceBasicSetting = instanceSetting.GetBasicSetting()
	}
	return instanceBasicSetting, nil
}

package scheduler_test

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/usememos/memos/internal/scheduler"
)

// TestRealWorldScenario tests a realistic multi-job scenario.
func TestRealWorldScenario(t *testing.T) {
	var (
		quickJobCount  atomic.Int32
		hourlyJobCount atomic.Int32
		logEntries     []string
		logMu          sync.Mutex
	)

	logger := &testLogger{
		onInfo: func(msg string, _ ...interface{}) {
			logMu.Lock()
			logEntries = append(logEntries, fmt.Sprintf("INFO: %s", msg))
			logMu.Unlock()
		},
		onError: func(msg string, _ ...interface{}) {
			logMu.Lock()
			logEntries = append(logEntries, fmt.Sprintf("ERROR: %s", msg))
			logMu.Unlock()
		},
	}

	s := scheduler.New(
		scheduler.WithTimezone("UTC"),
		scheduler.WithMiddleware(
			scheduler.Recovery(func(jobName string, r interface{}) {
				t.Logf("Job %s panicked: %v", jobName, r)
			}),
			scheduler.Logging(logger),
			scheduler.Timeout(5*time.Second),
		),
	)

	// Quick job (every second)
	s.Register(&scheduler.Job{
		Name:     "quick-check",
		Schedule: "* * * * * *",
		Handler: func(_ context.Context) error {
			quickJobCount.Add(1)
			time.Sleep(100 * time.Millisecond)
			return nil
		},
	})

	// Slower job (every 2 seconds)
	s.Register(&scheduler.Job{
		Name:     "slow-process",
		Schedule: "*/2 * * * * *",
		Handler: func(_ context.Context) error {
			hourlyJobCount.Add(1)
			time.Sleep(500 * time.Millisecond)
			return nil
		},
	})

	// Start scheduler
	if err := s.Start(); err != nil {
		t.Fatalf("failed to start scheduler: %v", err)
	}

	// Let it run for 5 seconds
	time.Sleep(5 * time.Second)

	// Graceful shutdown
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	if err := s.Stop(ctx); err != nil {
		t.Fatalf("failed to stop scheduler: %v", err)
	}

	// Verify execution counts
	quick := quickJobCount.Load()
	slow := hourlyJobCount.Load()

	t.Logf("Quick job ran %d times", quick)
	t.Logf("Slow job ran %d times", slow)

	if quick < 4 {
		t.Errorf("expected quick job to run at least 4 times, ran %d", quick)
	}

	if slow < 2 {
		t.Errorf("expected slow job to run at least 2 times, ran %d", slow)
	}

	// Verify logging
	logMu.Lock()
	defer logMu.Unlock()

	hasStartLog := false
	hasCompleteLog := false
	for _, entry := range logEntries {
		if contains(entry, "Job started") {
			hasStartLog = true
		}
		if contains(entry, "Job completed") {
			hasCompleteLog = true
		}
	}

	if !hasStartLog {
		t.Error("expected job start logs")
	}
	if !hasCompleteLog {
		t.Error("expected job completion logs")
	}
}

// TestCancellationDuringExecution verifies jobs can be canceled mid-execution.
func TestCancellationDuringExecution(t *testing.T) {
	var canceled atomic.Bool
	var started atomic.Bool

	s := scheduler.New()

	s.Register(&scheduler.Job{
		Name:     "long-job",
		Schedule: "* * * * * *",
		Handler: func(ctx context.Context) error {
			started.Store(true)
			// Simulate long-running work
			for i := 0; i < 100; i++ {
				select {
				case <-ctx.Done():
					canceled.Store(true)
					return ctx.Err()
				case <-time.After(100 * time.Millisecond):
					// Keep working
				}
			}
			return nil
		},
	})

	if err := s.Start(); err != nil {
		t.Fatalf("failed to start: %v", err)
	}

	// Wait until job starts
	for i := 0; i < 30; i++ {
		if started.Load() {
			break
		}
		time.Sleep(100 * time.Millisecond)
	}

	if !started.Load() {
		t.Fatal("job did not start within timeout")
	}

	// Stop with reasonable timeout
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	if err := s.Stop(ctx); err != nil {
		t.Logf("stop returned error (may be expected): %v", err)
	}

	if !canceled.Load() {
		t.Error("expected job to detect cancellation")
	}
}

// TestTimezoneHandling verifies timezone-aware scheduling.
func TestTimezoneHandling(t *testing.T) {
	// Parse a schedule in a specific timezone
	schedule, err := scheduler.ParseCronExpression("0 9 * * *") // 9 AM
	if err != nil {
		t.Fatalf("failed to parse schedule: %v", err)
	}

	// Test in New York timezone
	nyc, err := time.LoadLocation("America/New_York")
	if err != nil {
		t.Fatalf("failed to load timezone: %v", err)
	}

	// Current time: 8:30 AM in New York
	now := time.Date(2025, 1, 15, 8, 30, 0, 0, nyc)

	// Next run should be 9:00 AM same day
	next := schedule.Next(now)
	expected := time.Date(2025, 1, 15, 9, 0, 0, 0, nyc)

	if !next.Equal(expected) {
		t.Errorf("next = %v, expected %v", next, expected)
	}

	// If it's already past 9 AM
	now = time.Date(2025, 1, 15, 9, 30, 0, 0, nyc)
	next = schedule.Next(now)
	expected = time.Date(2025, 1, 16, 9, 0, 0, 0, nyc)

	if !next.Equal(expected) {
		t.Errorf("next = %v, expected %v", next, expected)
	}
}

// TestErrorPropagation verifies error handling.
func TestErrorPropagation(t *testing.T) {
	var errorLogged atomic.Bool

	logger := &testLogger{
		onError: func(msg string, _ ...interface{}) {
			if msg == "Job failed" {
				errorLogged.Store(true)
			}
		},
	}

	s := scheduler.New(
		scheduler.WithMiddleware(
			scheduler.Logging(logger),
		),
	)

	s.Register(&scheduler.Job{
		Name:     "failing-job",
		Schedule: "* * * * * *",
		Handler: func(_ context.Context) error {
			return errors.New("intentional error")
		},
	})

	if err := s.Start(); err != nil {
		t.Fatalf("failed to start: %v", err)
	}

	// Let it run once
	time.Sleep(1500 * time.Millisecond)

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	if err := s.Stop(ctx); err != nil {
		t.Fatalf("failed to stop: %v", err)
	}

	if !errorLogged.Load() {
		t.Error("expected error to be logged")
	}
}

// TestPanicRecovery verifies panic recovery middleware.
func TestPanicRecovery(t *testing.T) {
	var panicRecovered atomic.Bool

	s := scheduler.New(
		scheduler.WithMiddleware(
			scheduler.Recovery(func(jobName string, r interface{}) {
				panicRecovered.Store(true)
				t.Logf("Recovered from panic in job %s: %v", jobName, r)
			}),
		),
	)

	s.Register(&scheduler.Job{
		Name:     "panicking-job",
		Schedule: "* * * * * *",
		Handler: func(_ context.Context) error {
			panic("intentional panic for testing")
		},
	})

	if err := s.Start(); err != nil {
		t.Fatalf("failed to start: %v", err)
	}

	// Let it run once
	time.Sleep(1500 * time.Millisecond)

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	if err := s.Stop(ctx); err != nil {
		t.Fatalf("failed to stop: %v", err)
	}

	if !panicRecovered.Load() {
		t.Error("expected panic to be recovered")
	}
}

// TestMultipleJobsWithDifferentSchedules verifies concurrent job execution.
func TestMultipleJobsWithDifferentSchedules(t *testing.T) {
	var (
		job1Count atomic.Int32
		job2Count atomic.Int32
		job3Count atomic.Int32
	)

	s := scheduler.New()

	// Job 1: Every second
	s.Register(&scheduler.Job{
		Name:     "job-1sec",
		Schedule: "* * * * * *",
		Handler: func(_ context.Context) error {
			job1Count.Add(1)
			return nil
		},
	})

	// Job 2: Every 2 seconds
	s.Register(&scheduler.Job{
		Name:     "job-2sec",
		Schedule: "*/2 * * * * *",
		Handler: func(_ context.Context) error {
			job2Count.Add(1)
			return nil
		},
	})

	// Job 3: Every 3 seconds
	s.Register(&scheduler.Job{
		Name:     "job-3sec",
		Schedule: "*/3 * * * * *",
		Handler: func(_ context.Context) error {
			job3Count.Add(1)
			return nil
		},
	})

	if err := s.Start(); err != nil {
		t.Fatalf("failed to start: %v", err)
	}

	// Let them run for 6 seconds
	time.Sleep(6 * time.Second)

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	if err := s.Stop(ctx); err != nil {
		t.Fatalf("failed to stop: %v", err)
	}

	// Verify counts (allowing for timing variance)
	c1 := job1Count.Load()
	c2 := job2Count.Load()
	c3 := job3Count.Load()

	t.Logf("Job 1 ran %d times, Job 2 ran %d times, Job 3 ran %d times", c1, c2, c3)

	if c1 < 5 {
		t.Errorf("expected job1 to run at least 5 times, ran %d", c1)
	}
	if c2 < 2 {
		t.Errorf("expected job2 to run at least 2 times, ran %d", c2)
	}
	if c3 < 1 {
		t.Errorf("expected job3 to run at least 1 time, ran %d", c3)
	}
}

